package com.bluepay.services;
import com.bluepay.database.DatabaseConnection;import com.bluepay.models.User;import com.bluepay.utils.SessionManager;import java.sql.*;import java.util.*;
public class AccountService {
 private long uid(){User u=SessionManager.getInstance().getUser();if(u==null)throw new IllegalStateException("Login required");return u.id();}
 public List<String[]> all(){List<String[]> a=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,bank_name,masked_number,holder_name,primary_account FROM accounts WHERE user_id=? ORDER BY primary_account DESC,id")){p.setLong(1,uid());try(ResultSet r=p.executeQuery()){while(r.next())a.add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)});}}catch(SQLException e){throw new RuntimeException(e);}return a;}
 public void add(String bank,String last4){if(bank.isBlank()||!last4.matches("\\d{4}"))throw new IllegalArgumentException("Enter a bank name and exactly 4 fictional account digits.");try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO accounts(user_id,bank_name,masked_number,holder_name,primary_account) VALUES(?,?,?,?,?)")){p.setLong(1,uid());p.setString(2,bank);p.setString(3,"XXXX XXXX "+last4);p.setString(4,SessionManager.getInstance().getUser().fullName());p.setInt(5,all().isEmpty()?1:0);p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
 public void primary(long id){try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("UPDATE accounts SET primary_account=0 WHERE user_id=?")){p.setLong(1,uid());p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE accounts SET primary_account=1 WHERE id=? AND user_id=?")){p.setLong(1,id);p.setLong(2,uid());if(p.executeUpdate()!=1)throw new IllegalArgumentException("Account not found.");}c.commit();}catch(Exception e){throw new RuntimeException(e);}}
 public void remove(long id){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM accounts WHERE id=? AND user_id=?")){p.setLong(1,id);p.setLong(2,uid());p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
}